∀ {K : Type u_3} {E : Type u_4} {inst : Field K} {inst_1 : AddCommGroup E} {inst_2 : _root_.Module K E}
  {topFormEquiv topFormEquiv_1 : ↥(⋀[K]^3 E) ≃ₗ[K] K},
  { topFormEquiv := topFormEquiv } = { topFormEquiv := topFormEquiv_1 } → topFormEquiv = topFormEquiv_1

∀ {m n : ℕ} {q_minus q_plus : ℤ} {det_trace_zero : ↑m * q_minus + ↑n * q_plus = 0} {orientation_neg : q_minus < 0}
  {orientation_pos : 0 < q_plus} {primitive : q_minus.gcd q_plus = 1} {q_minus_1 q_plus_1 : ℤ}
  {det_trace_zero_1 : ↑m * q_minus_1 + ↑n * q_plus_1 = 0} {orientation_neg_1 : q_minus_1 < 0}
  {orientation_pos_1 : 0 < q_plus_1} {primitive_1 : q_minus_1.gcd q_plus_1 = 1},
  { q_minus := q_minus, q_plus := q_plus, det_trace_zero := det_trace_zero, orientation_neg := orientation_neg,
        orientation_pos := orientation_pos, primitive := primitive } =
      { q_minus := q_minus_1, q_plus := q_plus_1, det_trace_zero := det_trace_zero_1,
        orientation_neg := orientation_neg_1, orientation_pos := orientation_pos_1, primitive := primitive_1 } →
    q_minus = q_minus_1 ∧ q_plus = q_plus_1

∀ {K : Type u_2} {inst : Field K} {Eminus : Type u_3} {inst_1 : AddCommGroup Eminus} {inst_2 : _root_.Module K Eminus}
  {toShadow toShadow_1 : Eminus ≃ₗ[K] TFPT.Carrier.YukawaRank.NegativeBlockShadow K},
  { toShadow := toShadow } = { toShadow := toShadow_1 } → toShadow = toShadow_1

∀ {A : Type u_1} {inst : Ring A} {Pm Pp : A} {idem_m : Pm * Pm = Pm} {idem_p : Pp * Pp = Pp} {orth_mp : Pm * Pp = 0}
  {orth_pm : Pp * Pm = 0} {complete : Pm + Pp = 1} {Pm_1 Pp_1 : A} {idem_m_1 : Pm_1 * Pm_1 = Pm_1}
  {idem_p_1 : Pp_1 * Pp_1 = Pp_1} {orth_mp_1 : Pm_1 * Pp_1 = 0} {orth_pm_1 : Pp_1 * Pm_1 = 0}
  {complete_1 : Pm_1 + Pp_1 = 1},
  { Pm := Pm, Pp := Pp, idem_m := idem_m, idem_p := idem_p, orth_mp := orth_mp, orth_pm := orth_pm,
        complete := complete } =
      { Pm := Pm_1, Pp := Pp_1, idem_m := idem_m_1, idem_p := idem_p_1, orth_mp := orth_mp_1, orth_pm := orth_pm_1,
        complete := complete_1 } →
    Pm = Pm_1 ∧ Pp = Pp_1

∀ {ΘL Θ0 Θv : ℕ → ℤ} {equidist : ∀ (n : ℕ), 15 * Θv n = ΘL n - Θ0 n} {doubling_even : ∀ (m : ℕ), Θ0 (2 * m) = ΘL m}
  {doubling_odd : ∀ (m : ℕ), Θ0 (2 * m + 1) = 0}
  {theta_id : ∀ (n : ℕ), n ≠ 0 → ΘL n = 240 * TfptCarrier.GaussianShells.sigma3 n} {ΘL_1 Θ0_1 Θv_1 : ℕ → ℤ}
  {equidist_1 : ∀ (n : ℕ), 15 * Θv_1 n = ΘL_1 n - Θ0_1 n} {doubling_even_1 : ∀ (m : ℕ), Θ0_1 (2 * m) = ΘL_1 m}
  {doubling_odd_1 : ∀ (m : ℕ), Θ0_1 (2 * m + 1) = 0}
  {theta_id_1 : ∀ (n : ℕ), n ≠ 0 → ΘL_1 n = 240 * TfptCarrier.GaussianShells.sigma3 n},
  { ΘL := ΘL, Θ0 := Θ0, Θv := Θv, equidist := equidist, doubling_even := doubling_even, doubling_odd := doubling_odd,
        theta_id := theta_id } =
      { ΘL := ΘL_1, Θ0 := Θ0_1, Θv := Θv_1, equidist := equidist_1, doubling_even := doubling_even_1,
        doubling_odd := doubling_odd_1, theta_id := theta_id_1 } →
    ΘL = ΘL_1 ∧ Θ0 = Θ0_1 ∧ Θv = Θv_1

∀ {modes : Finset ℤ} {mark_local : TFPT.Carrier.SeamDeckClosure.MarkLocal modes} {modes_1 : Finset ℤ}
  {mark_local_1 : TFPT.Carrier.SeamDeckClosure.MarkLocal modes_1},
  { modes := modes, mark_local := mark_local } = { modes := modes_1, mark_local := mark_local_1 } → modes = modes_1

∀ {K : Type u_1} {inst : Field K} {E : Type u_2} {inst_1 : AddCommGroup E} {inst_2 : _root_.Module K E}
  {inst_3 : FiniteDimensional K E} {ω : TFPT.Carrier.YukawaTrilinearForm.YukawaTrilinearForm K E}
  {injective : ω.ContractionInjective} {surjective : ω.ContractionSurjective} {nontrivial : Nontrivial E}
  {ω_1 : TFPT.Carrier.YukawaTrilinearForm.YukawaTrilinearForm K E} {injective_1 : ω_1.ContractionInjective}
  {surjective_1 : ω_1.ContractionSurjective} {nontrivial_1 : Nontrivial E},
  { ω := ω, injective := injective, surjective := surjective, nontrivial := nontrivial } =
      { ω := ω_1, injective := injective_1, surjective := surjective_1, nontrivial := nontrivial_1 } →
    ω = ω_1

∀ {K : Type u_1} {inst : Field K} {inst_1 : CharZero K} {M : Type u_2} {inst_2 : AddCommGroup M}
  {inst_3 : _root_.Module K M} {inst_4 : FiniteDimensional K M}
  {polarization : TFPT.Carrier.Polarization (Module.End K M)}
  {rank_neg : Module.finrank K ↥(LinearMap.range polarization.Pm) = 3}
  {rank_pos : Module.finrank K ↥(LinearMap.range polarization.Pp) = 2}
  {polarization_1 : TFPT.Carrier.Polarization (Module.End K M)}
  {rank_neg_1 : Module.finrank K ↥(LinearMap.range polarization_1.Pm) = 3}
  {rank_pos_1 : Module.finrank K ↥(LinearMap.range polarization_1.Pp) = 2},
  { polarization := polarization, rank_neg := rank_neg, rank_pos := rank_pos } =
      { polarization := polarization_1, rank_neg := rank_neg_1, rank_pos := rank_pos_1 } →
    polarization = polarization_1

∀ {K : Type u_1} [inst : Field K] {E : Type u_2} [inst_1 : AddCommGroup E] [inst_2 : _root_.Module K E]
  (b : Module.Basis (Fin 3) K E),
  TFPT.Carrier.YukawaStageDExistence.ofBasis b = { ω := exteriorPower.alternatingMapLinearEquiv b.det }

∀ {K : Type u_1} {E : Type u_2} {inst : Field K} {inst_1 : AddCommGroup E} {inst_2 : _root_.Module K E}
  {contraction : E ≃ₗ[K] ↥(⋀[K]^2 E) →ₗ[K] K} {nontrivial : Nontrivial E} {contraction_1 : E ≃ₗ[K] ↥(⋀[K]^2 E) →ₗ[K] K}
  {nontrivial_1 : Nontrivial E},
  { contraction := contraction, nontrivial := nontrivial } =
      { contraction := contraction_1, nontrivial := nontrivial_1 } →
    contraction = contraction_1

